<?php
$title='PDF 签名盖章';$desc='把签名图片或印章图片添加到 PDF 指定页面；文件只在浏览器中处理。';include '_header.php';
?>
<div class="tool-panel"><div class="sign-grid"><label>选择 PDF<input id="pdf" type="file" accept="application/pdf,.pdf"></label><label>选择签名 / 印章图片<input id="image" type="file" accept="image/png,image/jpeg"></label><label>页码范围<input id="pages" value="1" maxlength="30" placeholder="例如：1 或 1-3"></label><label>位置<select id="pos"><option value="br">右下角</option><option value="bl">左下角</option><option value="tr">右上角</option><option value="tl">左上角</option><option value="c">居中</option></select></label><label>图片宽度（pt）<input id="width" type="number" min="30" max="400" value="140"></label><label>边距（pt）<input id="margin" type="number" min="0" max="144" value="36"></label></div><div class="btn-row"><button class="btn" id="apply" type="button" disabled>添加签名图片</button><button class="btn success" id="download" type="button" disabled>下载新 PDF</button></div><p class="tip" id="info" role="status">支持 120 MB 以内、最多 300 页的 PDF；这会添加可见签名图片，不是数字证书签名。</p></div><style>.sign-grid{display:grid;grid-template-columns:repeat(3,minmax(160px,1fr));gap:12px}.sign-grid label{display:flex;flex-direction:column;gap:6px}.sign-grid input,.sign-grid select{width:100%}@media(max-width:650px){.sign-grid{grid-template-columns:1fr}}</style><script src="../static/vendor/pdf-lib.min.js"></script><script>(()=>{'use strict';const MAX_PDF=120*1024*1024,MAX_IMAGE=12*1024*1024,MAX_PAGES=300,$=id=>document.getElementById(id);let pdfFile=null,imageFile=null,result=null;function info(t,e=false){$('info').textContent=t;$('info').style.color=e?'#b91c1c':'';}function ready(){$('apply').disabled=!(pdfFile&&imageFile);}function parsePages(value,total){const m=value.trim().match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!m)throw new Error('页码范围请填写如 1 或 1-3。');const a=Number(m[1]),b=Number(m[2]||m[1]);if(a<1||b<a||b>total)throw new Error('页码范围超出 PDF 页数。');return[a,b];}async function apply(){if(!pdfFile||!imageFile||!window.PDFLib)return;try{const bytes=await pdfFile.arrayBuffer(),pdf=await PDFLib.PDFDocument.load(bytes.slice(0));if(pdf.getPageCount()>MAX_PAGES)throw new Error('PDF 最多 300 页。');const [start,end]=parsePages($('pages').value,pdf.getPageCount()),imageBytes=await imageFile.arrayBuffer(),image=imageFile.type==='image/png'?await pdf.embedPng(imageBytes):await pdf.embedJpg(imageBytes),width=Number($('width').value),margin=Number($('margin').value);if(!Number.isFinite(width)||width<30||width>400||!Number.isFinite(margin)||margin<0||margin>144)throw new Error('宽度或边距设置不正确。');const h=image.height/image.width*width;for(let i=start-1;i<end;i++){const p=pdf.getPage(i),s=p.getSize(),pos=$('pos').value;let x=margin,y=margin;if(pos==='br'){x=s.width-width-margin;y=margin;}if(pos==='tr'){x=s.width-width-margin;y=s.height-h-margin;}if(pos==='tl')y=s.height-h-margin;if(pos==='c'){x=(s.width-width)/2;y=(s.height-h)/2;}p.drawImage(image,{x:Math.max(0,x),y:Math.max(0,y),width:Math.min(width,s.width),height:Math.min(h,s.height)});}const out=await pdf.save();result=new Blob([out],{type:'application/pdf'});$('download').disabled=false;info('已添加到第 '+start+' 至 '+end+' 页，可下载新 PDF。');}catch(e){result=null;$('download').disabled=true;info(e.message||'处理失败。',true);}}function download(){if(!result)return;const u=URL.createObjectURL(result),a=document.createElement('a');a.href=u;a.download=(pdfFile.name||'document').replace(/\.pdf$/i,'')+'-已签名.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}$('pdf').addEventListener('change',e=>{const f=e.target.files[0];pdfFile=f&&f.type==='application/pdf'&&f.size<=MAX_PDF?f:null;info(pdfFile?'已选择 PDF。':'请选择 120 MB 以内的 PDF。',!pdfFile);ready();});$('image').addEventListener('change',e=>{const f=e.target.files[0];imageFile=f&&['image/png','image/jpeg'].includes(f.type)&&f.size<=MAX_IMAGE?f:null;info(imageFile?'已选择签名图片。':'请选择 12 MB 以内的 PNG 或 JPG。',!imageFile);ready();});$('apply').addEventListener('click',apply);$('download').addEventListener('click',download);})();</script><?php include '_footer.php'; ?>
